def sha_file(p: Path) -> str:
    h=hashlib.sha256()
    with p.open('rb') as f:
        for c in iter(lambda:f.read(1<<20),b''): h.update(c)
    return h.hexdigest()

def sha_bytes(b:bytes)->str:return hashlib.sha256(b).hexdigest()

def read_csv(p:Path):
    with p.open(newline='',encoding='utf-8') as f:return list(csv.DictReader(f))

def write_csv(p:Path, rows, fields):
    p.parent.mkdir(parents=True,exist_ok=True)
    with p.open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)

def norm(name:str)->PurePosixPath:
    if '\x00' in name: raise ValueError(f'NUL archive path: {name!r}')
    p=PurePosixPath(name.replace('\\','/'))
    if p.is_absolute() or any(x in ('','.','..') for x in p.parts) or (p.parts and ':' in p.parts[0]):
        raise ValueError(f'unsafe archive path: {name!r}')
    return p

# Exact predecessor evidence is the starting point, but all source bytes are rechecked.
s226=read_csv(E/'post-refactor-226-surface-accountability.csv')
s227=read_csv(E/'post-refactor-227-surface-accountability.csv')
pre_surfaces=s226+s227
surface_by={(r['donor'],r['path']):r for r in pre_surfaces}
if len(surface_by)!=1349: raise SystemExit(f'expected 1349 unique predecessor surfaces, got {len(surface_by)}')

# Archive admission and fresh extracted-byte equality for every donor file.
archive_rows=[]
for donor,(archive_name,root) in sorted(DONORS.items()):
    archive=ARCHIVES[donor]
    if not archive.is_file() or not root.is_dir(): raise SystemExit(f'missing donor input {donor}')
    with zipfile.ZipFile(archive) as z:
        if z.testzip() is not None: raise SystemExit(f'CRC failure {donor}')
        infos=z.infolist(); seen=set(); folded=set(); files=0; dirs=0; syms=0; total=0; roots=set()
        for info in infos:
            p=norm(info.filename); key=p.as_posix().rstrip('/'); roots.add(p.parts[0])
            if key in seen or key.casefold() in folded: raise SystemExit(f'duplicate/case collision {donor}:{key}')
            seen.add(key); folded.add(key.casefold()); total+=info.file_size
            mode=info.external_attr>>16; kind=stat.S_IFMT(mode)
            if kind not in (0,stat.S_IFREG,stat.S_IFDIR,stat.S_IFLNK): raise SystemExit(f'special archive member {donor}:{key}')
            if info.flag_bits&1: raise SystemExit(f'encrypted archive member {donor}:{key}')
            if info.is_dir(): dirs+=1; continue
            if kind==stat.S_IFLNK: syms+=1; continue
            files+=1
            rel=PurePosixPath(*p.parts[1:]).as_posix()
            row=surface_by.get((donor,rel))
            if row is None: raise SystemExit(f'archive file missing predecessor surface {donor}:{rel}')
            data=z.read(info); ah=sha_bytes(data); ph=sha_file(root/rel)
            if ah!=row['sha256'] or ph!=row['sha256']: raise SystemExit(f'byte mismatch {donor}:{rel}')
        if len(roots)!=1: raise SystemExit(f'{donor} archive root count {len(roots)}')
        archive_rows.append({'donor':donor,'archive':archive.name,'archive_sha256':sha_file(archive),'members':len(infos),'files':files,'directories':dirs,'symlinks':syms,'uncompressed_bytes':total,'validation':'CRC,path,duplicate,case,special,encryption,archive-vs-extracted-vs-predecessor-SHA verified'})

# Re-emit all 1,349 surfaces with a fresh-review envelope. No file disappears behind a module-level row.
surfaces=[]
for r in sorted(pre_surfaces,key=lambda x:(x['donor'],x['path'])):
    root=DONORS[r['donor']][1]; p=root/r['path']
    if not p.is_file(): raise SystemExit(f'missing extracted donor file {r["donor"]}:{r["path"]}')
    h=sha_file(p)
    if h!=r['sha256']: raise SystemExit(f'fresh donor hash mismatch {r["donor"]}:{r["path"]}')
    wave='226' if r['donor']!='sni-spoofing-rust' else '227'
    surfaces.append({**r,'predecessor_wave':wave,'post_refactor_228_review':'fresh-byte-reverified-and-semantic-row-revisited'})

# Recompute directory/root Merkle records directly from current extracted donors.
directories=[]
for donor,(_,root) in sorted(DONORS.items()):
    files=sorted([p for p in root.rglob('*') if p.is_file()],key=lambda p:p.relative_to(root).as_posix())
    dirs=[root]+sorted([p for p in root.rglob('*') if p.is_dir()],key=lambda p:p.relative_to(root).as_posix())
    for d in dirs:
        entries=[]
        for p in files:
            try: rel=p.relative_to(d).as_posix()
            except ValueError: continue
            entries.append((rel,sha_file(p)))
        payload=''.join(f'{h}  {rel}\n' for rel,h in entries).encode()
        directories.append({'donor':donor,'path':'.' if d==root else d.relative_to(root).as_posix(),'descendant_files':len(entries),'tree_sha256':sha_bytes(payload)})

# Definition accountability is preserved only after exact source-hash revalidation. Earlier extraction was also freshly rerun in 228 and matched byte-for-byte.
symbols=[]
