# Resolve donor evidence hashes dynamically.
def evidence_hash(donor,path):
    if donor=='target-requirement' or path=='n/a': return 'n/a'
    row=surface_by.get((donor,path))
    if row is None: raise SystemExit(f'new record donor evidence missing {donor}:{path}')
    return row['sha256']

new_records=[]
for spec in new_specs:
    (rid,parent,cg,donor,domain,value,gran,form,sep,path,symbol,trans,topo,disp,rationale,cap,nodes,inv,neg,test,op,migration,license_note,risk,deps,conf,status)=spec
    new_records.append(dict(zip(LEDGER_FIELDS,[rid,parent,cg,donor,domain,value,gran,form,sep,path,evidence_hash(donor,path),symbol,trans,topo,disp,rationale,cap,nodes,inv,neg,test,op,migration,license_note,risk,deps,conf,status])))
new_ids={r['record_id'] for r in new_records}
if len(new_ids)!=len(new_records): raise SystemExit('duplicate 228 record id')

# Map predecessor semantic rows to refined units by donor/path/domain. Every row still gets an explicit review row.
def refinements(wave,r):
    d=r['donor']; p=r['donor_path']; out=[]
    if d=='ssh' and p in ('keys.go','keys_test.go'):out+=['PR228-S001','PR228-S002']
    if d in ('subconverter','srsc') and ('rule' in p.lower() or 'convertor' in p.lower() or 'config/proxygroup' in p.lower() or 'snippets/groups' in p.lower()):out+=['PR228-RULE001']
    if d=='subconverter' and ('proxygroup' in p.lower() or 'snippets/groups' in p.lower()):out+=['PR228-GROUP001','PR228-GROUP002']
    if d=='browser-ext':out+=['PR228-B001','PR228-B002']
    if d=='paas-gateway':out+=['PR228-GW001']
    if d=='reverse-tls':out+=['PR228-GW002']
    if d=='mwgp':out+=['PR228-WG001','PR228-WG002']
    if d=='shadowsocks-rust' and ('service/local.rs' in p or p=='README.md'):out+=['PR228-SS001']
    if d=='shadowsocksr':out+=['PR228-SSR001']
    if d=='sni-spoofing-rust' and p=='src/config.rs':out+=['PR228-SNI001']
    if d=='sni-spoofing-rust' and p=='src/sniffer/macos.rs':out+=['PR228-SNI002']
    if d=='sni-spoofing-rust' and p=='data/scan-snis.txt':out+=['PR228-SNICORPUS']
    if d=='sni-spoofing-rust' and (p=='src/bin/ui.rs' or p.startswith('releases/')):out+=['PR228-SNIUI']
    if d=='tsheadroom' and p in ('pool.go','pool_test.go','worker.py','tests/test_worker_protocol.py'):out+=['PR228-WORK001','PR228-WORK002','PR228-WORK003']
    if d=='tinytun' and p=='src/process_lookup.rs':out+=['PR228-TUN001']
    if d=='tinytun' and ('ebpf' in p.lower() or p=='src/packet/bypass.rs'):out+=['PR228-TUN002']
    if d=='srsc' and p.startswith('cache/'):out+=['PR228-CACHE001']
    if d=='tailscale-client':out+=['PR228-TAIL001']
    if d=='tools' and (p.startswith('data/') or p.startswith('json/')):out+=['PR228-TOOLS001']
    return sorted(set(out))

